	return load.aggregate_where(q.graph.client.conn, 'books', 'id', q.graph.client.prepare_query('books', q.query)!, .max, 'pages')
}

// mean_pages returns the mean of `pages` over the matching rows, in one
// query; 0 when none has a value.
pub fn (q BookQuery) mean_pages() !f64 {
	return load.aggregate_where(q.graph.client.conn, 'books', 'id', q.graph.client.prepare_query('books', q.query)!, .avg, 'pages')
}

// BookGroupBy groups the rows of a `BookQuery`. Start one with `group_by`.
pub struct BookGroupBy {
	query BookQuery
pub:
	columns    []string
	aggregates []load.Aggregate
}

// group_by groups the matching rows by `columns`. It needs a vgraph driver.
pub fn (q BookQuery) group_by(columns ...string) BookGroupBy {
	return BookGroupBy{
		query:   q
		columns: columns
	}
}

// aggregate adds what each group gets, such as `vgraph.count()` or
// `vgraph.sum('views')`.
pub fn (g BookGroupBy) aggregate(aggregates ...load.Aggregate) BookGroupBy {
	mut all := g.aggregates.clone()
	all << aggregates
	return BookGroupBy{
		...g
		aggregates: all
	}
}

// all returns the groups, ordered by their columns.
pub fn (g BookGroupBy) all() ![]load.Group {
	q := g.query
	return load.group_where(q.graph.client.conn, 'books', q.graph.client.prepare_query('books', q.query)!, g.columns.map(load.GroupColumn{
		name: it
		typ:  book_column_type(it)
	}), g.aggregates)
}

// scan reads the groups into `T`, by name: its fields named after the grouped
// columns and the aggregates (`count`, `sum_views`).
pub fn (g BookGroupBy) scan[T]() ![]T {
	return load.scan_groups[T](g.all()!)
}

// book_column_type returns the V type of a column of `books`.
fn book_column_type(column string) string {
	return match column {
		'id' { 'int' }
		'title' { 'string' }
		'year' { 'int' }
		'pages' { 'int' }
		else { '' }
	}
}

// order_by_authors_count orders the rows by their number of `authors`.
pub fn (q BookQuery) order_by_authors_count() BookQuery {
	return q.order_by(load.Order{
		expr: '(SELECT COUNT(*) FROM "book_authors" AS "t1" WHERE "t1"."book_id" = "t0"."id")'
	})
}

// order_by_authors_count_desc orders the rows by their number of `authors`, most
// first.
pub fn (q BookQuery) order_by_authors_count_desc() BookQuery {
	return q.order_by(load.Order{
		expr: '(SELECT COUNT(*) FROM "book_authors" AS "t1" WHERE "t1"."book_id" = "t0"."id")'
		desc: true
	})
}

// with_named_authors loads `authors` as `configure` says into
// `named_authors[name]`, besides any other load of it.
pub fn (q BookQuery) with_named_authors(name string, configure ...fn (AuthorQuery) AuthorQuery) BookQuery {
	mut next := q
	mut named := q.named_authors.clone()
	named[name] = configure
	next.named_authors = named
	return next
}

// with_authors loads each row's `authors` (many_to_many `authors`) with it, in one
// query for all the rows. `configure` narrows them, and can load their edges.
pub fn (q BookQuery) with_authors(configure ...fn (AuthorQuery) AuthorQuery) BookQuery {
	mut next := q
	next.with_authors = true
	next.authors_fns = configure
	return next
}

// all returns the matching rows, with the requested edges.
pub fn (q BookQuery) all() ![]BookNode {
	rows := load.select_where[models.Book](q.graph.client.conn, q.graph.client.prepare_query('books', q.query)!)!
	return q.nodes(rows)
}

// first returns the first matching row, with the requested edges, or a
// `NotFoundError`.
pub fn (q BookQuery) first() !BookNode {
	nodes := q.limit(1).all()!
	if nodes.len == 0 {
		return NotFoundError{
			table: 'books'
		}
	}
	return nodes[0]
}

// nodes loads the requested edges onto `rows`, which the caller already has: one
// query per edge, however many rows there are.
pub fn (q BookQuery) nodes(rows []models.Book) ![]BookNode {
	mut nodes := rows.map(BookNode{
		graph: q.graph
		book:  it
	})
	if q.with_authors {
		found := q.load_authors(rows, q.authors_fns)!
		for mut node in nodes {
			node.authors = found[node.book.id.str()] or { [] }
			node.loaded << 'authors'
		}
	}
	for name, fns in q.named_authors {
		found := q.load_authors(rows, fns)!
		for mut node in nodes {
			node.named_authors[name] = found[node.book.id.str()] or { [] }
		}
	}
	return nodes
}

// load_authors loads the `authors` of `rows`, keyed by each row's key.
fn (q BookQuery) load_authors(rows []models.Book, fns []fn (AuthorQuery) AuthorQuery) !map[string][]AuthorNode {
	mut sub := q.graph.authors()
	for configure in fns {
		sub = configure(sub)
	}
	if sub.query.limit > 0 || sub.query.offset > 0 {
		prepared := q.graph.client.prepare_edge_query('authors', sub.query)!
		cut := load.link_each(q.graph.client.conn, 'book_authors', 'book_id', 'author_id',
			rows.map(it.id.str()), .int, .int, 'authors', 'id', load.Query{
				...prepared
				conds: prepared.conds
			})!
		// the targets by key: the join rows give their order
		found := sub.nodes(load.select_in[models.Author](q.graph.client.conn, 'id',
			load.unique(cut.map(it[1])),
			query: load.Query{ ...prepared, order: '', desc: false, orders: []load.Order{}, limit: 0, offset: 0 }
		)!)!
		mut by_key := map[string]AuthorNode{}
		for target in found {
			by_key[target.author.id.str()] = target
		}
		mut cut_linked := map[string][]AuthorNode{}
		for pair in cut {
			if target := by_key[pair[1]] {
				cut_linked[pair[0]] << target
			}
		}
		return cut_linked
	}
	pairs := load.link_pairs(q.graph.client.conn, 'book_authors', 'book_id',
		'author_id', rows.map(it.id.str()), .int, .int)!
	// each parent's targets in the order of the query: one select per group of
	// parents, so each parent's order comes from one statement
	mut linked := map[string][]AuthorNode{}
	for group in load.parent_groups(pairs) {
		targets := sub.nodes(load.select_in[models.Author](q.graph.client.conn, 'id',
			load.unique(group.map(it[1])),
			query: q.graph.client.prepare_edge_query('authors', sub.query)!
		)!)!
		mut parents_of := map[string][]string{}
		for pair in group {
			parents_of[pair[1]] << pair[0]
		}
		for target in targets {
			for parent in parents_of[target.author.id.str()] or { [] } {
				linked[parent] << target
			}
		}
	}
	return linked
}

// authors_or_err returns the `authors`, or a `NotLoadedError` when the query
// didn't load them.
pub fn (n BookNode) authors_or_err() ![]AuthorNode {
	if 'authors' !in n.loaded {
		return NotLoadedError{
			edge: 'books.authors'
		}
	}
	return n.authors
}

// query_authors starts a query of this row's `authors`. It reads the join
// table `book_authors` first, so it can fail.
pub fn (n BookNode) query_authors() !AuthorQuery {
	pairs := load.link_pairs(n.graph.client.conn, 'book_authors', 'book_id',
		'author_id', [n.book.id.str()], .int, .int)!
	return n.graph.authors().where(load.in_keys('id', pairs.map(it[1]), .int))
}
